(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanilla';

  // --- Model ---

  function TodoModel(storage) {
    this.storage = storage;
    this.todos = this.storage.read();
    this.activeFilter = 'all';
    this.lastID = this.todos.reduce(function (max, t) { return Math.max(max, t.id); }, 0);
  }

  TodoModel.prototype.nextID = function () {
    return ++this.lastID;
  };

  TodoModel.prototype.save = function () {
    this.storage.write(this.todos);
  };

  TodoModel.prototype.getTodos = function (filter) {
    if (filter === 'active') {
      return this.todos.filter(function (t) { return !t.completed; });
    }
    if (filter === 'completed') {
      return this.todos.filter(function (t) { return t.completed; });
    }
    return this.todos;
  };

  // --- Store (localStorage) ---

  function Store(key) {
    this.key = key;
  }

  Store.prototype.read = function () {
    var data = localStorage.getItem(this.key);
    return data ? JSON.parse(data) : [];
  };

  Store.prototype.write = function (todos) {
    localStorage.setItem(this.key, JSON.stringify(todos));
  };

  // --- View ---

  function View() {
    this.$newTodo = document.querySelector('.new-todo');
    this.$todoList = document.querySelector('.todo-list');
    this.$main = document.querySelector('.main');
    this.$footer = document.querySelector('.footer');
    this.$toggleAll = document.querySelector('#toggle-all');
    this.$todoCount = document.querySelector('.todo-count');
    this.$clearCompleted = document.querySelector('.clear-completed');
    this.$filters = document.querySelectorAll('.filters a');
  }

  View.prototype.render = function (todos, activeFilter) {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;
    var hasTodos = todos.length > 0;

    // Show/hide main and footer
    this.$main.style.display = hasTodos ? 'block' : 'none';
    this.$footer.style.display = hasTodos ? 'block' : 'none';

    // Render list items
    this.$todoList.innerHTML = '';
    var self = this;
    todos.forEach(function (todo) {
      var li = document.createElement('li');
      if (todo.completed) {
        li.className = 'completed';
      }
      li.dataset.id = todo.id;

      var viewDiv = document.createElement('div');
      viewDiv.className = 'view';

      var toggle = document.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      if (todo.completed) {
        toggle.checked = true;
      }

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';

      viewDiv.appendChild(toggle);
      viewDiv.appendChild(label);
      viewDiv.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;

      li.appendChild(viewDiv);
      li.appendChild(editInput);
      self.$todoList.appendChild(li);
    });

    // Update toggle-all
    this.$toggleAll.checked = todos.length > 0 && activeCount === 0;

    // Update count
    var countText = activeCount === 1 ? '1 item left' : activeCount + ' items left';
    this.$todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

    // Update clear completed button
    this.$clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

    // Update filter links
    this.$filters.forEach(function (a) {
      var href = a.getAttribute('href');
      if (href === '#/' || href === '#') {
        a.className = activeFilter === 'all' ? 'selected' : '';
      } else if (href === '#/active') {
        a.className = activeFilter === 'active' ? 'selected' : '';
      } else if (href === '#/completed') {
        a.className = activeFilter === 'completed' ? 'selected' : '';
      }
    });
  };

  View.prototype.bind = function (event, handler) {
    var self = this;
    if (event === 'newTodo') {
      this.$newTodo.addEventListener('keyup', function (e) {
        if (e.keyCode === ENTER_KEY) {
          handler(self.$newTodo.value);
          self.$newTodo.value = '';
        }
      });
    } else if (event === 'toggleAll') {
      this.$toggleAll.addEventListener('change', function (e) {
        handler(e.target.checked);
      });
    } else if (event === 'toggleItem') {
      this.$todoList.addEventListener('change', function (e) {
        if (e.target.className === 'toggle') {
          var li = e.target.closest('li');
          handler(parseInt(li.dataset.id, 10), e.target.checked);
        }
      });
    } else if (event === 'destroyItem') {
      this.$todoList.addEventListener('click', function (e) {
        if (e.target.className === 'destroy') {
          var li = e.target.closest('li');
          handler(parseInt(li.dataset.id, 10));
        }
      });
    } else if (event === 'editItem') {
      this.$todoList.addEventListener('dblclick', function (e) {
        if (e.target.tagName === 'LABEL') {
          var li = e.target.closest('li');
          li.className = li.className + ' editing';
          var editInput = li.querySelector('.edit');
          editInput.value = li.querySelector('label').textContent;
          editInput.focus();
        }
      });
    } else if (event === 'editSave') {
      this.$todoList.addEventListener('keyup', function (e) {
        if (e.target.className === 'edit') {
          var li = e.target.closest('li');
          if (e.keyCode === ENTER_KEY) {
            li.className = li.className.replace(' editing', '');
            handler(parseInt(li.dataset.id, 10), e.target.value);
          } else if (e.keyCode === ESCAPE_KEY) {
            li.className = li.className.replace(' editing', '');
            var editInput = li.querySelector('.edit');
            editInput.value = li.querySelector('label').textContent;
          }
        }
      });
    } else if (event === 'editBlur') {
      this.$todoList.addEventListener('focusout', function (e) {
        if (e.target.className === 'edit') {
          var li = e.target.closest('li');
          li.className = li.className.replace(' editing', '');
          handler(parseInt(li.dataset.id, 10), e.target.value);
        }
      });
    } else if (event === 'clearCompleted') {
      this.$clearCompleted.addEventListener('click', function () {
        handler();
      });
    } else if (event === 'routeChange') {
      self.$filters.forEach(function (a) {
        a.addEventListener('click', function (e) {
          var href = a.getAttribute('href');
          if (href === '#/' || href === '#') {
            handler('all');
          } else if (href === '#/active') {
            handler('active');
          } else if (href === '#/completed') {
            handler('completed');
          }
        });
      });
    }
  };

  // --- Controller ---

  function Controller(model, view) {
    this.model = model;
    this.view = view;
    this.activeFilter = 'all';

    var self = this;
    this.view.bind('newTodo', function (title) {
      self.addTodo(title);
    });
    this.view.bind('toggleAll', function (checked) {
      self.toggleAll(checked);
    });
    this.view.bind('toggleItem', function (id, checked) {
      self.toggleItem(id, checked);
    });
    this.view.bind('destroyItem', function (id) {
      self.destroyItem(id);
    });
    this.view.bind('editSave', function (id, title) {
      self.saveEdit(id, title);
    });
    this.view.bind('editBlur', function (id, title) {
      self.saveEdit(id, title);
    });
    this.view.bind('clearCompleted', function () {
      self.clearCompleted();
    });
    this.view.bind('routeChange', function (filter) {
      self.setFilter(filter);
    });

    // Listen for hash changes
    window.addEventListener('hashchange', function () {
      self.applyRoute();
    });
  }

  Controller.prototype.addTodo = function (title) {
    title = title.trim();
    if (title === '') { return; }
    this.model.todos.push({
      id: this.model.nextID(),
      title: title,
      completed: false
    });
    this.model.save();
    this.render();
  };

  Controller.prototype.toggleAll = function (checked) {
    this.model.todos.forEach(function (t) { t.completed = checked; });
    this.model.save();
    this.render();
  };

  Controller.prototype.toggleItem = function (id, checked) {
    this.model.todos.forEach(function (t) {
      if (t.id === id) { t.completed = checked; }
    });
    this.model.save();
    this.render();
  };

  Controller.prototype.destroyItem = function (id) {
    this.model.todos = this.model.todos.filter(function (t) { return t.id !== id; });
    this.model.save();
    this.render();
  };

  Controller.prototype.saveEdit = function (id, title) {
    title = title.trim();
    if (title === '') {
      this.destroyItem(id);
      return;
    }
    this.model.todos.forEach(function (t) {
      if (t.id === id) { t.title = title; }
    });
    this.model.save();
    this.render();
  };

  Controller.prototype.clearCompleted = function () {
    this.model.todos = this.model.todos.filter(function (t) { return !t.completed; });
    this.model.save();
    this.render();
  };

  Controller.prototype.setFilter = function (filter) {
    this.activeFilter = filter;
    this.render();
  };

  Controller.prototype.applyRoute = function () {
    var hash = window.location.hash;
    if (hash === '#/active') {
      this.activeFilter = 'active';
    } else if (hash === '#/completed') {
      this.activeFilter = 'completed';
    } else {
      this.activeFilter = 'all';
    }
    this.render();
  };

  Controller.prototype.render = function () {
    var filtered = this.model.getTodos(this.activeFilter);
    this.view.render(filtered, this.activeFilter);
  };

  // --- Bootstrap ---

  function init() {
    var store = new Store(STORAGE_KEY);
    var model = new TodoModel(store);
    var view = new View();
    var controller = new Controller(model, view);

    // Apply the initial route
    controller.applyRoute();
  }

  // Wait for the DOM to be ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('node:assert');

// Helpers shared across steps

function getStyleDisplay(el) {
  return el.ownerDocument.defaultView.getComputedStyle(el).display;
}

function getTodoListItems() {
  return Array.from(document.querySelectorAll('.todo-list li'));
}

function findTodoItem(title) {
  return getTodoListItems().find(function (li) {
    return li.querySelector('label').textContent === title;
  });
}

function todoExists(title) {
  return !!findTodoItem(title);
}

// Convenience: wait for next tick so the app settles
function nextTick() {
  return new Promise(function (resolve) { setTimeout(resolve, 0); });
}

// Given steps

Given('the app has loaded', async function () {
  // app is loaded by Before hook in world.js
  await nextTick();
});

Given('there are no todos', function () {
  // Ensure clean state
  while (this.localStorage.getItem('todos-vanilla')) {
    this.localStorage.removeItem('todos-vanilla');
  }
  // Reload
  this.loadApp();
});

Given('a todo {string} exists', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = todos.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  todos.push({ id: maxId + 1, title: title, completed: false });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.loadApp();
});

Given('todos {string}, {string}, {string} exist', function (t1, t2, t3) {
  var todos = [];
  var id = 0;
  [t1, t2, t3].forEach(function (title) {
    todos.push({ id: ++id, title: title, completed: false });
  });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.loadApp();
});

Given('todos {string}, {string} exist', function (t1, t2) {
  var todos = [];
  var id = 0;
  [t1, t2].forEach(function (title) {
    todos.push({ id: ++id, title: title, completed: false });
  });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.loadApp();
});

Given('{string} is completed', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  todos.forEach(function (t) {
    if (t.title === title) t.completed = true;
  });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.loadApp();
});

Given('a completed todo {string} exists', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = todos.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  todos.push({ id: maxId + 1, title: title, completed: true });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.loadApp();
});

Given('there is a stored todo with title {string}', function (title) {
  var existing = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = existing.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  existing.push({ id: maxId + 1, title: title, completed: false });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(existing));
});

Given('there is a stored completed todo with title {string}', function (title) {
  var existing = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = existing.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  existing.push({ id: maxId + 1, title: title, completed: true });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(existing));
});

Given('the new todo input has value {string}', function (value) {
  var input = document.querySelector('.new-todo');
  input.value = value;
});

// When steps

When('I press Enter in the new todo input', function () {
  var input = document.querySelector('.new-todo');
  var event = new window.KeyboardEvent('keyup', { keyCode: 13, bubbles: true });
  input.dispatchEvent(event);
});

When('I click the toggle for {string}', function (title) {
  var li = findTodoItem(title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var toggle = li.querySelector('.toggle');
  toggle.checked = !toggle.checked;
  var event = new window.Event('change', { bubbles: true });
  toggle.dispatchEvent(event);
});

When('I click the toggle-all checkbox', function () {
  var toggleAll = document.querySelector('#toggle-all');
  toggleAll.checked = true;
  var event = new window.Event('change', { bubbles: true });
  toggleAll.dispatchEvent(event);
});

When('I click the destroy button for {string}', function (title) {
  var li = findTodoItem(title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var destroy = li.querySelector('.destroy');
  var event = new window.MouseEvent('click', { bubbles: true });
  destroy.dispatchEvent(event);
});

When('I double-click {string}', function (title) {
  var li = findTodoItem(title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var label = li.querySelector('label');
  var event = new window.MouseEvent('dblclick', { bubbles: true });
  label.dispatchEvent(event);
});

When('I change the edit input to {string}', function (newValue) {
  var li = document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo is currently being edited');
  var editInput = li.querySelector('.edit');
  editInput.value = newValue;
});

When('I press Enter in the edit input', function () {
  var li = document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo is currently being edited');
  var editInput = li.querySelector('.edit');
  var event = new window.KeyboardEvent('keyup', { keyCode: 13, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I press Escape in the edit input', function () {
  var li = document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo is currently being edited');
  var editInput = li.querySelector('.edit');
  var event = new window.KeyboardEvent('keyup', { keyCode: 27, bubbles: true });
  editInput.dispatchEvent(event);
});

When('the edit input loses focus', function () {
  var li = document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo is currently being edited');
  var editInput = li.querySelector('.edit');
  var event = new window.Event('focusout', { bubbles: true });
  editInput.dispatchEvent(event);
});

When('I click the clear completed button', function () {
  var btn = document.querySelector('.clear-completed');
  var event = new window.MouseEvent('click', { bubbles: true });
  btn.dispatchEvent(event);
});

When('the route is {string}', function (route) {
  this.navigate(route);
});

When('the app loads', function () {
  this.loadApp();
});

// Then steps

Then('{string} is not visible', function (selector) {
  var el = document.querySelector(selector);
  if (!el) return; // not in DOM is fine
  var display = getStyleDisplay(el);
  // If element is hidden by display:none or visibility
  if (display !== 'none') {
    // Check if it's a hidden section
    assert.strictEqual(el.offsetParent, null, 'Expected "' + selector + '" to be hidden');
  }
});

Then('a todo item with title {string} appears in the list', function (title) {
  assert.ok(todoExists(title), 'Todo "' + title + '" should exist in the list');
});

Then('the new todo input is cleared', function () {
  assert.strictEqual(document.querySelector('.new-todo').value, '');
});

Then('the todo list is empty', function () {
  assert.strictEqual(getTodoListItems().length, 0);
});

Then('{string} is marked as completed', function (title) {
  var li = findTodoItem(title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  assert.ok(li.classList.contains('completed'), 'Todo "' + title + '" should have class "completed"');
});

Then('all todos are marked as completed', function () {
  getTodoListItems().forEach(function (li) {
    assert.ok(li.classList.contains('completed'), 'All todos should be completed');
  });
});

Then('{string} is not completed', function (title) {
  var li = findTodoItem(title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  assert.ok(!li.classList.contains('completed'), 'Todo "' + title + '" should not have class "completed"');
});

Then('the toggle-all checkbox is checked', function () {
  assert.ok(document.querySelector('#toggle-all').checked);
});

Then('{string} is not in the todo list', function (title) {
  assert.ok(!todoExists(title), 'Todo "' + title + '" should not exist in the list');
});

Then('{string} is in the todo list', function (title) {
  assert.ok(todoExists(title), 'Todo "' + title + '" should exist in the list');
});

Then('a todo with title {string} appears in the list', function (title) {
  assert.ok(todoExists(title), 'Todo "' + title + '" should exist in the list');
});

Then('the todo count shows {string}', function (expected) {
  var countEl = document.querySelector('.todo-count');
  assert.ok(countEl, 'Todo count element should exist');
  assert.strictEqual(countEl.textContent.trim(), expected);
});

Then('the active count is wrapped in a <strong> element', function () {
  var strong = document.querySelector('.todo-count strong');
  assert.ok(strong, 'There should be a <strong> element in .todo-count');
  assert.ok(parseInt(strong.textContent, 10) > 0, 'The strong element should contain a number');
});

Then('the clear completed button is not visible', function () {
  var btn = document.querySelector('.clear-completed');
  assert.strictEqual(getStyleDisplay(btn), 'none');
});

Then('localStorage contains a todo with title {string}', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var match = todos.some(function (t) { return t.title === title; });
