const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// Helpers — take document from the calling step's context

function getTodoListItems(doc) {
  return Array.from(doc.querySelectorAll('.todo-list li'));
}

function findTodoItem(doc, title) {
  return getTodoListItems(doc).find(function (li) {
    return li.querySelector('label').textContent === title;
  });
}

function todoExists(doc, title) {
  return !!findTodoItem(doc, title);
}

function getStyleDisplay(el) {
  return el.ownerDocument.defaultView.getComputedStyle(el).display;
}

// Given steps

Given('the app has loaded', function () {
  // app is loaded by Before hook in world.js; settle on next tick
  return new Promise(function (resolve) { setTimeout(resolve, 10); });
});

Given('there are no todos', function () {
  while (this.localStorage.getItem('todos-vanilla')) {
    this.localStorage.removeItem('todos-vanilla');
  }
  this.refreshApp();
});

Given('todos {string}, {string}, {string} exist', function (t1, t2, t3) {
  var todos = [];
  [t1, t2, t3].forEach(function (title, i) {
    todos.push({ id: i + 1, title: title, completed: false });
  });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.refreshApp();
});

Given('todos {string}, {string} exist', function (t1, t2) {
  var todos = [];
  [t1, t2].forEach(function (title, i) {
    todos.push({ id: i + 1, title: title, completed: false });
  });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.refreshApp();
});

Given('todos {string} exist', function (t1) {
  var todos = [{ id: 1, title: t1, completed: false }];
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.refreshApp();
});

Given('a todo {string} exists', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = todos.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  todos.push({ id: maxId + 1, title: title, completed: false });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.refreshApp();
});

Given('a completed todo {string} exists', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = todos.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  todos.push({ id: maxId + 1, title: title, completed: true });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.refreshApp();
});

Given('{string} is completed', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  todos.forEach(function (t) {
    if (t.title === title) t.completed = true;
  });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.refreshApp();
});

Given('the new todo input has value {string}', function (value) {
  this.document.querySelector('.new-todo').value = value;
});

Given('there is a stored todo with title {string}', function (title) {
  var existing = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = existing.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  existing.push({ id: maxId + 1, title: title, completed: false });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(existing));
});

Given('there is a stored completed todo with title {string}', function (title) {
  var existing = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var maxId = existing.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  existing.push({ id: maxId + 1, title: title, completed: true });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(existing));
});

// When steps

When('I press Enter in the new todo input', function () {
  var input = this.document.querySelector('.new-todo');
  var event = new this.window.KeyboardEvent('keyup', { keyCode: 13, bubbles: true });
  input.dispatchEvent(event);
});

When('I click the toggle for {string}', function (title) {
  var li = findTodoItem(this.document, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var toggle = li.querySelector('.toggle');
  toggle.checked = !toggle.checked;
  var event = new this.window.Event('change', { bubbles: true });
  toggle.dispatchEvent(event);
});

When('I click the toggle-all checkbox', function () {
  var toggleAll = this.document.querySelector('#toggle-all');
  toggleAll.checked = true;
  var event = new this.window.Event('change', { bubbles: true });
  toggleAll.dispatchEvent(event);
});

When('I click the destroy button for {string}', function (title) {
  var li = findTodoItem(this.document, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var destroy = li.querySelector('.destroy');
  var event = new this.window.MouseEvent('click', { bubbles: true });
  destroy.dispatchEvent(event);
});

When('I double-click {string}', function (title) {
  var li = findTodoItem(this.document, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var label = li.querySelector('label');
  var event = new this.window.MouseEvent('dblclick', { bubbles: true });
  label.dispatchEvent(event);
});

When('I change the edit input to {string}', function (newValue) {
  var editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) {
    // Debug: log all li classes
    var items = this.document.querySelectorAll('.todo-list li');
    console.log('EDITING DEBUG: found ' + items.length + ' items');
    Array.from(items).forEach(function(li, i) { console.log('  li[' + i + '] class=' + li.className); });
    throw new Error('No todo is currently being edited');
  }
  var editInput = editing.querySelector('.edit');
  editInput.value = newValue;
});

When('I press Enter in the edit input', function () {
  var editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo is currently being edited');
  var editInput = editing.querySelector('.edit');
  var event = new this.window.KeyboardEvent('keyup', { keyCode: 13, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I press Escape in the edit input', function () {
  var editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo is currently being edited');
  var editInput = editing.querySelector('.edit');
  var event = new this.window.KeyboardEvent('keyup', { keyCode: 27, bubbles: true });
  editInput.dispatchEvent(event);
});

When('the edit input loses focus', function () {
  var editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo is currently being edited');
  var editInput = editing.querySelector('.edit');
  var event = new this.window.Event('focusout', { bubbles: true });
  editInput.dispatchEvent(event);
});

When('I click the clear completed button', function () {
  var btn = this.document.querySelector('.clear-completed');
  var event = new this.window.MouseEvent('click', { bubbles: true });
  btn.dispatchEvent(event);
});

When('the route is {string}', function (route) {
  if (route === '#/') route = '#/';
  this.navigate(route);
});

When('the app loads', function () {
  this.refreshApp();
});

// Then steps

Then('the element with selector {string} is hidden', function (selector) {
  var el = this.document.querySelector(selector);
  if (!el) return;
  var display = getStyleDisplay(el);
  if (display !== 'none') {
    assert.strictEqual(el.offsetParent, null, 'Expected "' + selector + '" to be hidden');
  }
});

Then('a todo item with title {string} appears in the list', function (title) {
  assert.ok(todoExists(this.document, title), 'Todo "' + title + '" should exist in the list');
});

Then('the new todo input is cleared', function () {
  assert.strictEqual(this.document.querySelector('.new-todo').value, '');
});

Then('the todo list is empty', function () {
  assert.strictEqual(getTodoListItems(this.document).length, 0);
});

Then('{string} is marked as completed', function (title) {
  var li = findTodoItem(this.document, title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  assert.ok(li.classList.contains('completed'), 'Todo "' + title + '" should have class "completed"');
});

Then('all todos are marked as completed', function () {
  getTodoListItems(this.document).forEach(function (li) {
    assert.ok(li.classList.contains('completed'), 'All todos should be completed');
  });
});

Then('{string} is not completed', function (title) {
  var li = findTodoItem(this.document, title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  assert.ok(!li.classList.contains('completed'), 'Todo "' + title + '" should not have class "completed"');
});

Then('the toggle-all checkbox is checked', function () {
  assert.ok(this.document.querySelector('#toggle-all').checked);
});

Then('{string} is not in the todo list', function (title) {
  assert.ok(!todoExists(this.document, title), 'Todo "' + title + '" should not exist in the list');
});

Then('{string} is in the todo list', function (title) {
  assert.ok(todoExists(this.document, title), 'Todo "' + title + '" should exist in the list');
});

Then('a todo with title {string} appears in the list', function (title) {
  assert.ok(todoExists(this.document, title), 'Todo "' + title + '" should exist in the list');
});

Then('the todo count shows {string}', function (expected) {
  var countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'Todo count element should exist');
  assert.strictEqual(countEl.textContent.trim(), expected);
});

Then('the active count is wrapped in a <strong> element', function () {
  var strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'There should be a <strong> element in .todo-count');
  assert.ok(parseInt(strong.textContent, 10) > 0, 'The strong element should contain a number');
});

Then('the clear completed button is not visible', function () {
  var btn = this.document.querySelector('.clear-completed');
  assert.strictEqual(getStyleDisplay(btn), 'none');
});

Then('localStorage contains a todo with title {string}', function (title) {
  var todos = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  var match = todos.some(function (t) { return t.title === title; });
  assert.ok(match, 'localStorage should contain a todo with title "' + title + '"');
});

Then('the visible todos are {string} and {string}', function (t1, t2) {
  var items = getTodoListItems(this.document);
  var labels = items.map(function (li) { return li.querySelector('label').textContent; });
  assert.strictEqual(labels.length, 2);
  assert.ok(labels.indexOf(t1) >= 0);
  assert.ok(labels.indexOf(t2) >= 0);
});

Then('only {string} is visible', function (title) {
  var items = getTodoListItems(this.document);
  assert.strictEqual(items.length, 1);
  assert.strictEqual(items[0].querySelector('label').textContent, title);
});

Then('the {string} filter link has class {string}', function (linkText, className) {
  var links = this.document.querySelectorAll('.filters a');
  console.log('FILTER DEBUG: found ' + links.length + ' links');
  Array.from(links).forEach(function(a, i) {
    console.log('  link[' + i + '] href=' + a.getAttribute('href') + ' text=' + JSON.stringify(a.textContent.trim()) + ' class=' + a.className);
  });
  var found = Array.from(links).filter(function (a) { return a.textContent.trim() === linkText; });
  console.log('FILTER DEBUG: matches for "' + linkText + '": ' + found.length);
  assert.strictEqual(found.length, 1);
  assert.ok(found[0].classList.contains(className));
});

Then('the {string} filter link does not have class {string}', function (linkText, className) {
  var links = this.document.querySelectorAll('.filters a');
  var found = Array.from(links).filter(function (a) { return a.textContent.trim() === linkText; });
  assert.strictEqual(found.length, 1);
  assert.ok(!found[0].classList.contains(className));
});

Then('the todo {string} is not visible', function (title) {
  var items = getTodoListItems(this.document);
  var match = items.some(function (li) { return li.querySelector('label').textContent === title; });
  assert.ok(!match, 'Todo "' + title + '" should not be visible');
});

