// Re-evaluate the app source in the current window, preserving localStorage.
// Loads the page HTML and re-runs app.js so the app re-reads from whatever
// localStorage currently holds.
refreshApp() {
  const indexPath = path.join(ROOT, 'index.html');
  const appPath = path.join(ROOT, 'js', 'app.js');
  const appSource = fs.readFileSync(appPath, 'utf8');

  // happy-dom (pilot 0.13.64) document.write on a closed document appends
  // instead of replacing.  Explicitly open + close via innerHTML replacement
  // on the document element, then create a fresh app instance.
  const html = fs.readFileSync(indexPath, 'utf8');
  // Replace the entire document content the spec way:
  // open() clears and puts readyState back to 'loading'
  this.window.location.hash = '';   // reset hash
  while (this.document.body && this.document.body.firstChild) {
    this.document.body.removeChild(this.document.body.firstChild);
  }
  while (this.document.head && this.document.head.firstChild) {
    this.document.head.removeChild(this.document.head.firstChild);
  }
  // Write the new HTML
  this.document.write(html);
  this.document.close();
  this.window.eval(appSource);
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));
}

